changeSet.sql:
ALTER TABLE activity_types
ADD COLUMN general BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE activity_types
ADD COLUMN unique_general TINYINT
GENERATED ALWAYS AS (
CASE WHEN general = TRUE THEN 1 ELSE NULL END
) STORED;

ALTER TABLE activity_types
ADD CONSTRAINT uq_activity_types_unique_general
UNIQUE (unique_general);

ALTER TABLE categories
ADD COLUMN work BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE categories
ADD COLUMN unique_work TINYINT
GENERATED ALWAYS AS (
CASE WHEN work = TRUE THEN 1 ELSE NULL END
) STORED;

ALTER TABLE categories
ADD CONSTRAINT uq_categories_unique_work
UNIQUE (unique_work);
